// Procesa TODOS los ítems (una nota por noticia).
// El id/orden vienen del nodo "Get many rows" (el HTML del HTTP Request no los tiene).
const salida = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const html = items[i].json.data;

  const regex = /<script type="application\/ld\+json">(.*?)<\/script>/gs;
  let match;
  let articleBody = null;

  while ((match = regex.exec(html)) !== null) {
    try {
      const json = JSON.parse(match[1]);
      if (json.articleBody) {
        articleBody = json.articleBody;
        break;
      }
    } catch (e) {
      continue;
    }
  }

  if (!articleBody) {
    throw new Error("No se encontró articleBody en una de las notas.");
  }

  // Recupero id y orden de la noticia original, en la misma posición.
  const noticia = $('Get many rows').all()[i].json;

  salida.push({
    json: {
      id: noticia.id,
      orden: noticia.orden,
      texto_nota: articleBody,
    },
  });
}

return salida;

