// Parsea la respuesta de Groq y arrastra también el texto de la fuente.
const salida = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const content = items[i].json.choices[0].message.content;

  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    throw new Error("No se pudo parsear la respuesta de Groq: " + content);
  }

  // Recupero datos de la noticia desde ExtraerTexto (id, orden, texto_nota).
  const extraido = $('Code in JavaScript').all()[i].json;
  // Recupero la URL de la fuente desde el nodo que leyó las noticias.
  const noticia = $('Get many rows').all()[i].json;
  const url = (noticia.fuentes_urls && noticia.fuentes_urls[0]) || "";

  salida.push({
    json: {
      id: extraido.id,
      orden: extraido.orden,
      titulo: parsed.titulo,
      cuerpo: parsed.cuerpo,
      // Lista de fuentes con su texto (preparado para multi-fuente).
      textos_fuentes: [{ url: url, texto: extraido.texto_nota }],
    },
  });
}

return salida;

// Colapsa a un solo ítem para marcar el status de la edición una sola vez.
// Recupero el edicion_id desde el nodo que leyó las noticias.
const noticia = $('Get many rows').first().json;
return [{ json: { edicion_id: noticia.edicion_id } }];
